import unittest
from candidate import correct_bracketing


class TestCorrectBracketing(unittest.TestCase):
    def test_correct_bracketing_empty_string(self):
        self.assertTrue(correct_bracketing(""))

    def test_correct_bracketing_single_open_bracket(self):
        self.assertFalse(correct_bracketing("<"))

    def test_correct_bracketing_single_close_bracket(self):
        self.assertFalse(correct_bracketing(">"))

    def test_correct_bracketing_simple_valid_pair(self):
        self.assertTrue(correct_bracketing("<>"))

    def test_correct_bracketing_wrong_order_start_with_close(self):
        self.assertFalse(correct_bracketing("><<>"))

    def test_correct_bracketing_deeply_nested_valid(self):
        self.assertTrue(correct_bracketing("<<><>>"))

    def test_correct_bracketing_unbalanced_more_closes(self):
        self.assertFalse(correct_bracketing(">>"))

    def test_correct_bracketing_unbalanced_more_opens(self):
        self.assertFalse(correct_bracketing("<<<"))

    def test_correct_bracketing_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            correct_bracketing(None)

    def test_correct_bracketing_invalid_type_raises_type_error(self):
        with self.assertRaises(TypeError):
            correct_bracketing(123)
